import unittest

from mathlib import digit_sum, fib, gcd, is_prime, lcm


class T(unittest.TestCase):
    def test_gcd(self):
        self.assertEqual(gcd(84, 36), 12)
        self.assertEqual(gcd(7, 0), 7)

    def test_lcm(self):
        self.assertEqual(lcm(4, 6), 12)
        self.assertEqual(lcm(0, 5), 0)

    def test_is_prime(self):
        self.assertEqual([n for n in range(20) if is_prime(n)], [2, 3, 5, 7, 11, 13, 17, 19])

    def test_fib(self):
        self.assertEqual([fib(i) for i in range(8)], [0, 1, 1, 2, 3, 5, 8, 13])

    def test_digit_sum(self):
        self.assertEqual(digit_sum(9875), 29)
        self.assertEqual(digit_sum(-12), 3)


if __name__ == "__main__":
    unittest.main()
